(function(){'use strict';const PAGE_SIZE=100;const DAY_SECONDS=86400;const TROVE_OFFSET_SECONDS=11*3600;const PICKER_DAYS=7;const state={anchors:[],days:[],anchor:null,selectedDayIdx:null,boards:[],boardFilter:'',selectedUuid:null,entries:[],entriesTotal:0,loadingEntries:false,hotRetentionDays:3,};const $dayPicker=document.getElementById('lb-day-picker');const $boardSearch=document.getElementById('lb-board-search');const $boardList=document.getElementById('lb-board-list');const $entriesTitle=document.getElementById('lb-entries-title');const $entriesMeta=document.getElementById('lb-entries-meta');const $entriesBody=document.getElementById('lb-entries-body');const $entriesFoot=document.getElementById('lb-entries-foot');const $loadMore=document.getElementById('lb-load-more');const $playerSearch=document.getElementById('lb-player-search');const $playerPanel=document.getElementById('lb-player-panel');const $playerName=document.getElementById('lb-player-name');const $playerBody=document.getElementById('lb-player-body');const $playerClose=document.getElementById('lb-player-close');const $mobileTrigger=document.getElementById('lb-mobile-trigger');const $mobileSelected=document.getElementById('lb-mobile-selected');const $sidebar=document.getElementById('lb-sidebar');init().catch((err)=>{console.error('[leaderboards] boot failed',err);$boardList.innerHTML=errorHTML(err);});async function init(){const[stamps,config]=await Promise.all([fetchJSON('/site/leaderboards/timestamps'),fetchJSON('/site/leaderboards/config').catch(()=>null),]);state.anchors=stamps.items||[];if(config&&Number.isFinite(config.hot_retention_days)){state.hotRetentionDays=config.hot_retention_days;}
renderSubtitle();buildDays();renderDayPicker();if(!state.days.some((d)=>d.anchor!=null)){$boardList.innerHTML=`<p class="lb-board-empty" data-i18n>No leaderboard data has been captured yet. Check back later.</p>`;rerunI18n();wireEvents();return;}
const hash=parseHash();let startIdx=-1;if(hash.anchor){startIdx=state.days.findIndex((d)=>d.anchor===hash.anchor);}
if(startIdx<0){startIdx=state.days.findIndex((d)=>d.anchor!=null);}
await selectDay(startIdx);const initialBoard=hash.board!=null&&state.boards.find((b)=>b.uuid===hash.board);if(initialBoard)selectBoard(initialBoard.uuid);wireEvents();}
function renderSubtitle(){const el=document.getElementById('lb-subtitle');if(!el)return;const template=t('Top players per board, ranked. Hourly captures, {days}-day live retention, full archive beyond.');el.textContent=template.replace('{days}',String(state.hotRetentionDays));}
function troveDayKeyFor(unix){return Math.floor((unix-TROVE_OFFSET_SECONDS)/DAY_SECONDS);}
function buildDays(){const now=Math.floor(Date.now()/1000);const todayKey=troveDayKeyFor(now);const byDay=new Map();for(const ts of state.anchors){const key=troveDayKeyFor(ts);const prev=byDay.get(key);if(prev==null||ts>prev)byDay.set(key,ts);}
state.days=[];for(let i=0;i<PICKER_DAYS;i++){const key=todayKey-i;const dayStart=key*DAY_SECONDS+TROVE_OFFSET_SECONDS;const dayEnd=dayStart+DAY_SECONDS;const troveDate=new Date(dayStart*1000-TROVE_OFFSET_SECONDS*1000);state.days.push({key,troveDate,dayStart,dayEnd,anchor:byDay.get(key)||null,relative:i,});}}
function renderDayPicker(){if(!state.days.length){$dayPicker.innerHTML=`<span class="lb-day-loading" data-i18n>No captures yet</span>`;rerunI18n();return;}
$dayPicker.innerHTML=state.days.map((d,idx)=>{const cls=['lb-day'];if(d.anchor==null)cls.push('lb-day-empty');if(idx===state.selectedDayIdx)cls.push('active');const dis=d.anchor==null?'disabled aria-disabled="true"':'aria-selected="'+(idx===state.selectedDayIdx)+'"';const role=d.anchor==null?'':'role="tab"';return`
        <button type="button" class="${cls.join(' ')}" data-day-idx="${idx}" ${dis} ${role}>
          <span class="lb-day-rel" data-i18n>${dayRelativeLabel(d.relative)}</span>
          <span class="lb-day-date">${dayCalendarLabel(d.troveDate)}</span>
          ${d.anchor == null
            ? `<span class="lb-day-meta"data-i18n>No data</span>`
            : `<span class="lb-day-meta">${formatTroveTime(d.anchor)}</span>`}
        </button>`;}).join('');rerunI18n();for(const btn of $dayPicker.querySelectorAll('[data-day-idx]:not([disabled])')){btn.addEventListener('click',()=>selectDay(Number(btn.dataset.dayIdx)));}}
function dayRelativeLabel(rel){if(rel===0)return'Today';if(rel===1)return'Yesterday';return'Day';}
function dayCalendarLabel(troveDate){const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];const days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];return`${days[troveDate.getUTCDay()]} ${months[troveDate.getUTCMonth()]} ${troveDate.getUTCDate()}`;}
function formatTroveTime(unixAnchor){const trove=new Date((unixAnchor-TROVE_OFFSET_SECONDS)*1000);const pad=(n)=>String(n).padStart(2,'0');return`${pad(trove.getUTCHours())}:${pad(trove.getUTCMinutes())}`;}
async function selectDay(idx){if(idx<0||idx>=state.days.length)return;const day=state.days[idx];if(day.anchor==null)return;if(state.selectedDayIdx===idx&&state.anchor===day.anchor)return;state.selectedDayIdx=idx;state.anchor=day.anchor;renderDayPicker();updateHash();await loadBoards();}
async function fetchJSON(path){const res=await fetch(path,{headers:{Accept:'application/json'}});if(!res.ok){let msg=`HTTP ${res.status}`;try{const body=await res.json();if(body&&body.error&&body.error.message)msg=body.error.message;}catch(_){}
throw new Error(msg);}
return res.json();}
function formatAnchor(ts){const d=new Date(ts*1000);const pad=(n)=>String(n).padStart(2,'0');return`${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())} UTC`;}
async function loadBoards(){$boardList.innerHTML=`<p class="lb-loading">${t('Loading…')}</p>`;state.boards=[];state.selectedUuid=null;resetEntries();try{const data=await fetchJSON(`/site/leaderboards/boards?created_at=${state.anchor}`);state.boards=data.items||[];}catch(err){$boardList.innerHTML=errorHTML(err);return;}
renderBoardList();}
function renderBoardList(){if(!state.boards.length){$boardList.innerHTML=`<p class="lb-board-empty" data-i18n>No boards for this capture.</p>`;rerunI18n();return;}
const filter=state.boardFilter.toLowerCase();const visible=filter?state.boards.filter((b)=>b.name.toLowerCase().includes(filter)||(b.category||'').toLowerCase().includes(filter)):state.boards;if(!visible.length){$boardList.innerHTML=`<p class="lb-board-empty" data-i18n>No boards match your filter.</p>`;rerunI18n();return;}
const groups=new Map();for(const b of visible){const cat=b.category||'Other';if(!groups.has(cat))groups.set(cat,[]);groups.get(cat).push(b);}
const html=[];for(const[cat,boards]of groups){html.push(`<div class="lb-category">${esc(cat)}</div>`);for(const b of boards){const isActive=b.uuid===state.selectedUuid;const tag=b.contest_type?`<span class="lb-contest-tag">${esc(b.contest_type)}</span>`:'';html.push(`
          <button type="button" class="lb-board${isActive ? ' active' : ''}"
                  data-uuid="${b.uuid}" title="${esc(b.name)}">
            <span class="lb-board-name">${esc(b.name)}</span>
            ${tag}
          </button>`);}}
$boardList.innerHTML=html.join('');for(const btn of $boardList.querySelectorAll('[data-uuid]')){btn.addEventListener('click',()=>{selectBoard(Number(btn.dataset.uuid));$sidebar.classList.remove('open');$mobileTrigger.setAttribute('aria-expanded','false');});}}
function resetEntries(){state.entries=[];state.entriesTotal=0;$entriesTitle.setAttribute('data-i18n','');$entriesTitle.textContent='Pick a board to see entries';$entriesMeta.textContent='';$entriesBody.innerHTML=`<p class="lb-hint" data-i18n>Choose a board on the left to load its ranked entries.</p>`;$entriesFoot.hidden=true;rerunI18n();}
async function selectBoard(uuid){if(state.selectedUuid===uuid)return;state.selectedUuid=uuid;state.entries=[];state.entriesTotal=0;const board=state.boards.find((b)=>b.uuid===uuid);if(board){$entriesTitle.removeAttribute('data-i18n');if(window.BTTi18n&&window.BTTi18n.untrack)window.BTTi18n.untrack($entriesTitle);$entriesTitle.textContent=board.name;$mobileSelected.removeAttribute('data-i18n');if(window.BTTi18n&&window.BTTi18n.untrack)window.BTTi18n.untrack($mobileSelected);$mobileSelected.textContent=board.name;}
updateHash();for(const btn of $boardList.querySelectorAll('[data-uuid]')){btn.classList.toggle('active',Number(btn.dataset.uuid)===uuid);}
$entriesBody.innerHTML=`<p class="lb-loading" data-i18n>Loading…</p>`;$entriesFoot.hidden=true;rerunI18n();await loadMoreEntries(true);}
async function loadMoreEntries(reset=false){if(state.loadingEntries||state.selectedUuid==null)return;state.loadingEntries=true;if(!reset)$loadMore.disabled=true;const offset=reset?0:state.entries.length;try{const data=await fetchJSON(`/site/leaderboards/${state.selectedUuid}/entries`
+`?created_at=${state.anchor}&limit=${PAGE_SIZE}&offset=${offset}`,);state.entries=reset?(data.items||[]):state.entries.concat(data.items||[]);state.entriesTotal=data.total||0;renderEntries();}catch(err){$entriesBody.innerHTML=errorHTML(err);$entriesFoot.hidden=true;}finally{state.loadingEntries=false;$loadMore.disabled=false;}}
function renderEntries(){if(!state.entries.length){$entriesBody.innerHTML=`<p class="lb-hint" data-i18n>No entries for this board.</p>`;$entriesMeta.textContent='';$entriesFoot.hidden=true;rerunI18n();return;}
const rows=state.entries.map((e)=>`
      <div class="lb-td lb-rank ${rankClass(e.rank)}">${e.rank}</div>
      <div class="lb-td"><span class="lb-player" data-player="${esc(e.player_name)}"><span class="lb-player-icon"></span>${esc(e.player_name)}</span></div>
      <div class="lb-td lb-score">${esc(formatScore(e.score))}</div>
    `).join('');$entriesBody.innerHTML=`
      <div class="lb-entries-table">
        <div class="lb-th lb-rank" data-i18n>Rank</div>
        <div class="lb-th" data-i18n>Player</div>
        <div class="lb-th lb-score" data-i18n>Score</div>
        ${rows}
      </div>`;rerunI18n();const shown=state.entries.length;$entriesMeta.textContent=state.entriesTotal>shown?`${shown.toLocaleString()} / ${state.entriesTotal.toLocaleString()} ${t('entries')}`:`${shown.toLocaleString()} ${t('entries')}`;$entriesFoot.hidden=shown>=state.entriesTotal;for(const el of $entriesBody.querySelectorAll('[data-player]')){el.addEventListener('click',()=>{const name=el.dataset.player;$playerSearch.value=name;searchPlayer(name);});}}
function rankClass(rank){if(rank===1)return'lb-rank-top';if(rank===2)return'lb-rank-top-2';if(rank===3)return'lb-rank-top-3';return'';}
function formatScore(score){return Number.isInteger(score)?score.toLocaleString():Number(score).toLocaleString(undefined,{maximumFractionDigits:2});}
async function searchPlayer(name){const trimmed=(name||'').trim();if(!trimmed){$playerPanel.hidden=true;return;}
$playerPanel.hidden=false;$playerName.textContent=trimmed;$playerBody.innerHTML=`<p class="lb-loading" data-i18n>Loading…</p>`;rerunI18n();$playerPanel.scrollIntoView({behavior:'smooth',block:'nearest'});try{const data=await fetchJSON(`/site/leaderboards/players/${encodeURIComponent(trimmed)}/history?limit=50`,);const canonical=(data.items&&data.items.length&&data.items[0].player_name)||trimmed;$playerName.textContent=canonical;renderPlayerHistory(data.items||[]);}catch(err){$playerBody.innerHTML=errorHTML(err);}}
function renderPlayerHistory(items){if(!items.length){$playerBody.innerHTML=`<p class="lb-hint" data-i18n>No recent appearances found for this player.</p>`;rerunI18n();return;}
const nameByUuid=new Map(state.boards.map((b)=>[b.uuid,b.name]));$playerBody.innerHTML=items.map((it)=>{const boardName=nameByUuid.get(it.leaderboard)||`Board #${it.leaderboard}`;return`
        <div class="lb-player-row">
          <div class="lb-ph-board">${esc(boardName)}</div>
          <div class="lb-ph-rank">#${it.rank}</div>
          <div class="lb-ph-score">${esc(formatScore(it.score))}</div>
          <div class="lb-ph-when">${esc(formatAnchor(it.created_at))}</div>
        </div>`;}).join('');rerunI18n();}
function wireEvents(){$boardSearch.addEventListener('input',()=>{state.boardFilter=$boardSearch.value||'';renderBoardList();});$loadMore.addEventListener('click',()=>loadMoreEntries(false));let searchTimer=null;$playerSearch.addEventListener('input',()=>{clearTimeout(searchTimer);const val=$playerSearch.value.trim();if(!val){$playerPanel.hidden=true;return;}
searchTimer=setTimeout(()=>searchPlayer(val),350);});$playerSearch.addEventListener('keydown',(e)=>{if(e.key==='Enter'){e.preventDefault();clearTimeout(searchTimer);searchPlayer($playerSearch.value.trim());}});$playerClose.addEventListener('click',()=>{$playerPanel.hidden=true;$playerSearch.value='';});$mobileTrigger.addEventListener('click',()=>{const open=$sidebar.classList.toggle('open');$mobileTrigger.setAttribute('aria-expanded',String(open));});window.addEventListener('hashchange',async()=>{const hash=parseHash();if(hash.anchor&&hash.anchor!==state.anchor){const idx=state.days.findIndex((d)=>d.anchor===hash.anchor);if(idx>=0)await selectDay(idx);}
if(hash.board!=null&&hash.board!==state.selectedUuid){const exists=state.boards.find((b)=>b.uuid===hash.board);if(exists)selectBoard(hash.board);}});document.addEventListener('btt-lang-changed',()=>{renderSubtitle();renderDayPicker();if(state.selectedUuid)renderEntries();else resetEntries();renderBoardList();});}
function parseHash(){const out={anchor:null,board:null};const raw=location.hash.replace(/^#/,'');if(!raw)return out;const params=new URLSearchParams(raw);if(params.has('anchor'))out.anchor=Number(params.get('anchor'))||null;if(params.has('board'))out.board=Number(params.get('board'))||null;return out;}
function updateHash(){const parts=[];if(state.anchor)parts.push(`anchor=${state.anchor}`);if(state.selectedUuid!=null)parts.push(`board=${state.selectedUuid}`);const next=parts.length?'#'+parts.join('&'):location.pathname;history.replaceState(null,'',next);}
function t(s){return window.BTTi18n&&window.BTTi18n.t?window.BTTi18n.t(s):s;}
function rerunI18n(){if(window.BTTi18n&&window.BTTi18n.refresh)window.BTTi18n.refresh();}
function esc(s){return String(s??'').replace(/[&<>"']/g,(c)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function errorHTML(err){const msg=(err&&err.message)||String(err);return`<p class="lb-error">${t('Failed to load')}: ${esc(msg)}</p>`;}})();